import {
  consoleFetchJSON,
  GreenCheckCircleIcon,
  Silence,
  SilenceStates,
} from '@openshift-console/dynamic-plugin-sdk';
import { Button } from '@patternfly/react-core/dist/dynamic/components/Button';
import { Dropdown } from '@patternfly/react-core/dist/dynamic/components/Dropdown';
import { DropdownItem } from '@patternfly/react-core/dist/dynamic/components/Dropdown';
import { DropdownList } from '@patternfly/react-core/dist/dynamic/components/Dropdown';
import { Label } from '@patternfly/react-core/dist/dynamic/components/Label';
import { LabelGroup } from '@patternfly/react-core/dist/dynamic/components/Label';
import { MenuToggle } from '@patternfly/react-core/dist/dynamic/components/MenuToggle';
import { MenuToggleElement } from '@patternfly/react-core/dist/dynamic/components/MenuToggle';
import { Modal } from '@patternfly/react-core/dist/dynamic/components/Modal';
import { ModalBody } from '@patternfly/react-core/dist/dynamic/components/Modal';
import { ModalFooter } from '@patternfly/react-core/dist/dynamic/components/Modal';
import { ModalHeader } from '@patternfly/react-core/dist/dynamic/components/Modal';
import { ModalVariant } from '@patternfly/react-core/dist/dynamic/components/Modal';
import { Panel } from '@patternfly/react-core/dist/dynamic/components/Panel';
import { PanelMain } from '@patternfly/react-core/dist/dynamic/components/Panel';
import { PanelMainBody } from '@patternfly/react-core/dist/dynamic/components/Panel';
import { Alert as PFAlert } from '@patternfly/react-core/dist/dynamic/components/Alert';
import { BanIcon } from '@patternfly/react-icons/dist/dynamic/icons/ban-icon';
import { CheckCircleIcon } from '@patternfly/react-icons/dist/dynamic/icons/check-circle-icon';
import { EllipsisVIcon } from '@patternfly/react-icons/dist/dynamic/icons/ellipsis-v-icon';
import { HourglassHalfIcon } from '@patternfly/react-icons/dist/dynamic/icons/hourglass-half-icon';
import * as _ from 'lodash-es';
import type { FC, Ref } from 'react';
import { useState } from 'react';
import { useTranslation } from 'react-i18next';
import { useNavigate } from 'react-router';
import { useBoolean } from '../../../shared/hooks/useBoolean';
import {
  getEditSilenceAlertUrl,
  getFetchSilenceUrl,
  usePerspective,
} from '../../../shared/hooks/usePerspective';
import { useMonitoringNamespace } from '../../../shared/hooks/useMonitoringNamespace';
import { silenceMatcherEqualitySymbol, silenceState } from '../../../shared/utils/utils';
import { DataTestIDs } from '../../../shared/constants/data-test';

export const SilenceMatchersList = ({ silence }: { silence: Silence }) => (
  <LabelGroup numLabels={20}>
    {_.map(silence.matchers, ({ name, isEqual, isRegex, value }, i) => (
      <Label key={i}>
        <span>{name}</span>
        <span>{silenceMatcherEqualitySymbol(isEqual, isRegex)}</span>
        <span>{value}</span>
      </Label>
    ))}
  </LabelGroup>
);

type ExpireSilenceModalProps = {
  isOpen: boolean;
  setClosed: () => void;
  silenceID: string;
};

export const SilenceState = ({ silence }: { silence: Silence }) => {
  const { t } = useTranslation(process.env.I18N_NAMESPACE);

  const state = silenceState(silence);
  const icon = {
    [SilenceStates.Active]: <GreenCheckCircleIcon />,
    [SilenceStates.Pending]: <HourglassHalfIcon />,
    [SilenceStates.Expired]: <BanIcon data-test-id="ban-icon" />,
  }[state];

  const getStateKey = (stateData) => {
    switch (stateData) {
      case SilenceStates.Active:
        return t('Active');
      case SilenceStates.Pending:
        return t('Pending');
      default:
        return t('Expired');
    }
  };

  return icon ? (
    <>
      {icon} {getStateKey(state)}
    </>
  ) : null;
};

export const SilenceDropdown: FC<SilenceDropdownProps> = ({ silence, toggleText }) => {
  const { t } = useTranslation(process.env.I18N_NAMESPACE);
  const { perspective } = usePerspective();
  const navigate = useNavigate();
  const { namespace } = useMonitoringNamespace();

  const [isOpen, setIsOpen, , setClosed] = useBoolean(false);
  const [isModalOpen, , setModalOpen, setModalClosed] = useBoolean(false);

  const editSilence = () => {
    navigate(getEditSilenceAlertUrl(perspective, silence.id, namespace));
  };

  const dropdownItems =
    silenceState(silence) === SilenceStates.Expired
      ? [
          <DropdownItem
            data-test={DataTestIDs.SilenceRecreateDropdownItem}
            value={0}
            key="recreate-silence"
            onClick={editSilence}
          >
            {t('Recreate silence')}
          </DropdownItem>,
        ]
      : [
          <DropdownItem
            data-test={DataTestIDs.SilenceEditDropdownItem}
            value={0}
            key="edit-silence"
            onClick={editSilence}
          >
            {t('Edit silence')}
          </DropdownItem>,
          <DropdownItem
            data-test={DataTestIDs.SilenceExpireDropdownItem}
            value={1}
            key="cancel-silence"
            onClick={setModalOpen}
          >
            {t('Expire silence')}
          </DropdownItem>,
        ];

  return (
    <>
      <Dropdown
        isOpen={isOpen}
        onSelect={setClosed}
        data-test="silence-actions"
        popperProps={{ position: 'right' }}
        onOpenChange={(isOpen: boolean) => (isOpen ? setIsOpen() : setClosed())}
        toggle={(toggleRef: Ref<MenuToggleElement>) => (
          <MenuToggle
            ref={toggleRef}
            aria-label="kebab dropdown toggle"
            variant={toggleText ? 'default' : 'plain'}
            onClick={setIsOpen}
            isExpanded={isOpen}
            data-test={DataTestIDs.KebabDropdownButton}
          >
            {toggleText || <EllipsisVIcon />}
          </MenuToggle>
        )}
      >
        <DropdownList>{dropdownItems}</DropdownList>
      </Dropdown>
      <ExpireSilenceModal isOpen={isModalOpen} setClosed={setModalClosed} silenceID={silence.id} />
    </>
  );
};

export const ExpireSilenceModal: FC<ExpireSilenceModalProps> = ({
  isOpen,
  setClosed,
  silenceID,
}) => {
  const { t } = useTranslation(process.env.I18N_NAMESPACE);
  const { perspective } = usePerspective();
  const { namespace } = useMonitoringNamespace();

  const [isInProgress, , setInProgress, setNotInProgress] = useBoolean(false);
  const [success, , setSuccess] = useBoolean(false);
  const [errorMessage, setErrorMessage] = useState();

  const expireSilence = () => {
    setInProgress();
    const url = getFetchSilenceUrl(perspective, silenceID, namespace);
    consoleFetchJSON
      .delete(url)
      .then(() => {
        setNotInProgress();
        setSuccess();
        setTimeout(() => {
          setClosed();
        }, 1000);
      })
      .catch((err) => {
        setErrorMessage(_.get(err, 'json.error') || err.message || 'Error expiring silence');
        setNotInProgress();
      });
  };

  return (
    <Modal isOpen={isOpen} position="top" title={t('Expire silence')} variant={ModalVariant.small}>
      <ModalHeader title={t('Expire Silence')} />
      <ModalBody>
        {t('Are you sure you want to expire this silence?')}
        {errorMessage && (
          <PFAlert isInline title={t('An error occurred')} variant="danger">
            <Panel isScrollable>
              <PanelMain maxHeight="100px">
                <PanelMainBody>{errorMessage}</PanelMainBody>
              </PanelMain>
            </Panel>
          </PFAlert>
        )}
      </ModalBody>
      <ModalFooter>
        <Button
          variant="primary"
          onClick={expireSilence}
          isLoading={isInProgress}
          icon={success ? <CheckCircleIcon /> : null}
          data-test={DataTestIDs.ExpireSilenceButton}
        >
          {success ? t('Expired') : t('Expire silence')}
        </Button>
        <Button variant="secondary" onClick={setClosed} data-test={DataTestIDs.CancelButton}>
          {t('Cancel')}
        </Button>
      </ModalFooter>
    </Modal>
  );
};

type SilenceDropdownProps = {
  silence: Silence;
  toggleText?: string;
};
